result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/intervals.py", "content": """"Genomic interval algebra library (BED-style, 0-based half-open).

All intervals are (start, end) tuples with start < end, 0-based, half-open:
the interval covers bases start .. end-1.
"""

from __future__ import annotations

from typing import Iterable, List, Sequence, Tuple

Interval = Tuple[int, int]

__all__ = [
    "validate",
    "merge",
    "intersect",
    "subtract",
    "complement",
]


def validate(intervals: Iterable[Interval]) -> None:
    """Raise ValueError if any interval is malformed (start >= end or negative)."""
    for s, e in intervals:
        if not isinstance(s, int) or not isinstance(e, int):
            raise ValueError(f"interval ({s}, {e}) must contain integers")
        if s < 0 or e < 0:
            raise ValueError(f"interval ({s}, {e}) has negative coordinate")
        if s >= e:
            raise ValueError(
                f"invalid interval ({s}, {e}): start must be < end "
                "(empty intervals are not allowed)"
            )


def merge(intervals: Iterable[Interval]) -> List[Interval]:
    """Merge overlapping and book-ended intervals.

    Order-insensitive; result is sorted by start. Idempotent.
    """
    ivs = sorted(intervals)
    out: List[Interval] = []
    for s, e in ivs:
        if out and s <= out[-1][1]:  # overlap or book-ended (touching)
            ps, pe = out[-1]
            out[-1] = (ps, max(pe, e))
        else:
            out.append((s, e))
    return out


def intersect(a: Iterable[Interval], b: Iterable[Interval]) -> List[Interval]:
    """Intersect two interval sets; returns merged, sorted overlaps."""
    A = merge(a)
    B = merge(b)
    out: List[Interval] = []
    i = j = 0
    while i < len(A) and j < len(B):
        s = max(A[i][0], B[j][0])
        e = min(A[i][1], B[j][1])
        if s < e:
            out.append((s, e))
        if A[i][1] <= B[j][1]:
            i += 1
        else:
            j += 1
    return out


def subtract(a: Iterable[Interval], b: Iterable[Interval]) -> List[Interval]:
    """Subtract interval set b from interval set a."""
    A = merge(a)
    B = merge(b)
    out: List[Interval] = []
    for s, e in A:
        pieces: List[Interval] = [(s, e)]
        for bs, be in B:
            nxt: List[Interval] = []
            for ps, pe in pieces:
                if be <= ps or bs >= pe:
                    nxt.append((ps, pe))  # no overlap
                else:
                    if ps < bs:
                        nxt.append((ps, bs))
                    if be < pe:
                        nxt.append((be, pe))
            pieces = nxt
            if not pieces:
                break
        out.extend(pieces)
    return out


def complement(
    intervals: Iterable[Interval], chrom_length: int
) -> List[Interval]:
    """Complement of the merged intervals within a chromosome of given length."""
    if chrom_length < 0:
        raise ValueError("chrom_length must be non-negative")
    merged = merge(intervals)
    for s, e in merged:
        if e > chrom_length:
            raise ValueError(
                f"interval ({s}, {e}) exceeds chromosome length {chrom_length}"
            )
    out: List[Interval] = []
    pos = 0
    for s, e in merged:
        if pos < s:
            out.append((pos, s))
        pos = e
    if pos < chrom_length:
        out.append((pos, chrom_length))
    return out
