import pytest

from intervals import complement, intersect, merge, subtract


# ---------------------------------------------------------------------------
# Exact-answer tests from the spec
# ---------------------------------------------------------------------------

def test_merge_exact():
    assert merge([(1, 5), (4, 8), (10, 12)]) == [(1, 8), (10, 12)]


def test_intersect_exact():
    assert intersect([(1, 10)], [(5, 15)]) == [(5, 10)]


def test_subtract_exact():
    assert subtract([(0, 10)], [(3, 5)]) == [(0, 3), (5, 10)]


def test_complement_exact():
    assert complement([(2, 4), (6, 8)], 10) == [(0, 2), (4, 6), (8, 10)]


# ---------------------------------------------------------------------------
# Brute-force per-base bitmap reference implementation
# ---------------------------------------------------------------------------

def bitmap_set(intervals, length=None):
    """Represent an interval set as a set of covered base positions."""
    bm = set()
    for s, e in intervals:
        assert s < e
        bm.update(range(s, e))
    return bm


def bitmap_to_intervals(bm):
    """Convert a set of covered positions back into a merged interval list."""
    out = []
    for p in sorted(bm):
        if out and p == out[-1][1]:
            out[-1] = (out[-1][0], p + 1)
        else:
            out.append((p, p + 1))
    return out


def ref_merge(intervals):
    return bitmap_to_intervals(bitmap_set(intervals))


def ref_intersect(a, b):
    return bitmap_to_intervals(bitmap_set(a) & bitmap_set(b))


def ref_subtract(a, b):
    return bitmap_to_intervals(bitmap_set(a) - bitmap_set(b))


def ref_complement(intervals, chrom_length):
    return bitmap_to_intervals(set(range(chrom_length)) - bitmap_set(intervals))


# ---------------------------------------------------------------------------
# Property tests (seeded)
# ---------------------------------------------------------------------------

def random_interval_sets(rng, n_sets=40, max_coord=30, max_len=6):
    sets = []
    for _ in range(n_sets):
        k = rng.randint(0, 6)
        ivs = []
        for _ in range(k):
            s = rng.randint(0, max_coord - 2)
            e = min(max_coord, s + rng.randint(1, max_len))
            ivs.append((s, e))
        sets.append(ivs)
    return sets


def test_merge_property_idempotent_and_order_insensitive():
    rng = random.Random(17)
    for ivs in random_interval_sets(rng):
        m1 = merge(ivs)

        # idempotent
        assert merge(m1) == m1

        # order-insensitive: shuffled input gives same result
        for _ in range(5):
            shuffled = list(ivs)
            rng.shuffle(shuffled)
            assert merge(shuffled) == m1

        # agrees with brute-force bitmap implementation
        assert m1 == ref_merge(ivs)


def test_intersect_property():
    rng = random.Random(17)
    sets = random_interval_sets(rng)
    for a in sets:
        for b in sets:
            assert intersect(a, b) == ref_intersect(a, b)


def test_subtract_property():
    rng = random.Random(17)
    sets = random_interval_sets(rng)
    for a in sets:
        for b in sets:
            assert subtract(a, b) == ref_subtract(a, b)


def test_complement_property():
    rng = random.Random(17)
    for ivs in random_interval_sets(rng):
        assert complement(ivs, 30) == ref_complement(ivs, 30)


def test_complement_double_negation():
    rng = random.Random(17)
    for ivs in random_interval_sets(rng):
        comp = complement(ivs, 30)
        assert complement(comp, 30) == merge(ivs)


def test_validation_errors():
    with pytest.raises(ValueError):
        merge([(5, 5)])  # empty interval
    with pytest.raises(ValueError):
        merge([(4, 2)])  # inverted
    with pytest.raises(ValueError):
        complement([(0, 11)], 10)  # exceeds chromosome length
